<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_once __DIR__ . '/../includes/auth.php';
$user=current_user(); if(!$user||!in_array($user['role'],['Administrator','Bursar'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$start=trim((string)($_POST['period_start']??''));$end=trim((string)($_POST['period_end']??''));$currency=(string)($_POST['currency']??'');$valid=static function(string $v):bool{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)===1&&$d!==false&&$d->format('Y-m-d')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']));};
if(!$valid($start)||!$valid($end)||$end<$start||!in_array($currency,['USD','ZiG'],true)){$_SESSION['error']='Enter a valid payroll period and currency.';header('Location: ../?page=payroll');exit;}
$pdo=db();try{$pdo->beginTransaction();$schoolLock=$pdo->query('SELECT id FROM school_profile WHERE id=1 FOR UPDATE')->fetchColumn();if(!$schoolLock)throw new DomainException('School settings are missing. Restore the school profile before creating payroll.');$overlap=$pdo->prepare("SELECT id FROM payroll_runs WHERE currency=:currency AND status<>'Voided' AND period_start<=:end_date AND period_end>=:start_date LIMIT 1");$overlap->execute(['currency'=>$currency,'end_date'=>$end,'start_date'=>$start]);if($overlap->fetchColumn())throw new DomainException('This period overlaps another non-void '.$currency.' payroll run. Choose a period that does not overlap.');$run=$pdo->prepare("INSERT INTO payroll_runs(period_start,period_end,currency,status,created_by) VALUES(:start,:end,:currency,'Draft',:user)");$run->execute(['start'=>$start,'end'=>$end,'currency'=>$currency,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();$lines=$pdo->prepare("INSERT INTO payroll_lines(run_id,staff_id,staff_name,staff_number,job_title,base_salary,currency) SELECT :run,u.id,u.full_name,sp.staff_number,sp.job_title,ps.base_salary,ps.currency FROM users u JOIN staff_pay_settings ps ON ps.staff_id=u.id LEFT JOIN staff_profiles sp ON sp.user_id=u.id WHERE u.active=1 AND u.role IN ('Administrator','Head','Teacher','Bursar','Clerk') AND ps.active=1 AND ps.currency=:currency AND ps.effective_from<=:period AND ps.base_salary>0 ORDER BY u.full_name");$lines->execute(['run'=>$id,'currency'=>$currency,'period'=>$start]);if($lines->rowCount()<1)throw new DomainException('No active staff have an effective salary in '.$currency.' for this period. Set salaries first.');$count=$lines->rowCount();audit_log('payroll.run_created','payroll_runs',$id,['period_start'=>$start,'period_end'=>$end,'currency'=>$currency,'staff_count'=>$count]);$pdo->commit();$_SESSION['notice']='Draft payroll created for '.$count.' staff member(s).';header('Location: ../?page=payroll&run='.$id);exit;}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();error_log('Payroll run creation failed: '.$x->getMessage());$_SESSION['error']=$x instanceof DomainException?$x->getMessage():'Could not create payroll run. Check whether this period and currency already exist.';header('Location: ../?page=payroll');exit;}
